      ctx.fill();
    });

    // ship (draw once)
    ship.draw();

    // asteroids (gray with subtle outline)
    ctx.fillStyle = '#555';
    ctx.strokeStyle = '#aaa';
    ctx.lineWidth = 1;
    asteroids.forEach(a => {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
    });

    // power‑ups (glowing yellow)
    ctx.fillStyle = '#ff0';
    powerUps.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      ctx.shadowColor = '#ff0';
      ctx.shadowBlur = 8;
      ctx.fill();
      ctx.shadowBlur = 0;
    });

